import { el, btn, field, select, panel, row, grid, table, ready, dialog, download, csv } from '../ops-ui.js';
import { parseCsv } from '../network-csv.20261001.js';
const api = await ready('Diagram');
const p = panel('区域、图层与链路信息', '区域可分组、隐藏或锁定；链路可登记类型与速率。直角避障按节点位置计算，复杂图最多 50 个节点启用求路，每次刷新最多求解 12 条被遮挡链路，网格与搜索量也有限制；超过预算会明确提醒，仍可手工调节折线。');
const groupName = field('新区域名称'), group = select('将当前选中节点归属到', []), speed = field('当前链路速率（例如 10 Gbps）'), kind = select('链路类型', [['copper', '铜缆'], ['fiber', '光纤'], ['wireless', '无线'], ['virtual', '逻辑链路']]);
const layers = el('div'), checks = el('div'); groupName.input.maxLength = 80; speed.input.maxLength = 40;
p.append(grid(groupName.label, group.label, speed.label, kind.label), row(btn('创建区域', () => { const g = api.graph(), name = groupName.input.value.trim(); if (!name) throw Error('请输入区域名称'); g.groups = g.groups || []; g.groups.push({ id: crypto.randomUUID(), label: name, color: '#2563eb', locked: false, hidden: false }); api.update(g); groupName.input.value = ''; }), btn('应用区域到所选节点', () => { const ids = api.selection(), g = api.graph(); if (!ids.some(id => g.nodes.some(n => n.id === id))) throw Error('请先选择节点'); g.nodes.filter(n => ids.includes(n.id)).forEach(n => n.groupId = group.input.value); api.update(g); }), btn('锁定 / 解锁所选节点', () => { const ids = api.selection(), g = api.graph(), nodes = g.nodes.filter(n => ids.includes(n.id)); if (!nodes.length) throw Error('先选择节点'); const lock = !nodes.every(n => n.locked); nodes.forEach(n => n.locked = lock); api.update(g); }), btn('应用链路信息与避障', () => { const g = api.graph(), edge = g.edges.find(e => e.id === api.primary()); if (!edge) throw Error('请先在图中选择链路'); edge.speed = speed.input.value; edge.linkKind = kind.input.value; edge.avoid = true; api.update(g); }), btn('关闭所选链路避障', () => { const g = api.graph(), e = g.edges.find(e => e.id === api.primary()); if (!e) throw Error('请先选择链路'); e.avoid = false; api.update(g); })), layers, checks);
const names = { copper:'铜缆', fiber:'光纤', wireless:'无线', virtual:'逻辑' };
function render() {
  const g = api.graph(), old = group.input.value; group.input.replaceChildren(new Option('不属于区域', '')); (g.groups || []).forEach(r => group.input.add(new Option(r.label, r.id))); group.input.value = old;
  layers.replaceChildren(table(['区域', '设备数', '显示与编辑', '操作'], (g.groups || []).map(r => [r.label, g.nodes.filter(n => n.groupId === r.id).length, `${r.hidden?'隐藏':'显示'} · ${r.locked?'锁定':'可编辑'}`, row(btn(r.hidden?'显示':'隐藏',()=>changeGroup(r.id,'hidden')),btn(r.locked?'解锁':'锁定',()=>changeGroup(r.id,'locked')),btn('删除区域',()=>{const next=api.graph();next.groups=next.groups.filter(x=>x.id!==r.id);next.nodes.filter(n=>n.groupId===r.id).forEach(n=>n.groupId='');api.update(next)}))])));
  const warnings = [], routes = g.edges.slice(0,200).map(e => ({ e, r:api.route(e.id) }));
  for (const {e,r} of routes) if(r.unresolved)warnings.push(`${e.label||'未命名链路'}：未求得避障路径（可能触发计算预算），请手工调整或简化图形`);
  let crossings=0;
  for(let i=0;i<routes.length;i++) for(let j=i+1;j<routes.length;j++){const a=routes[i],b=routes[j];if([a.e.from,a.e.to].some(id=>id===b.e.from||id===b.e.to)||a.e.routing!=='orthogonal'||b.e.routing!=='orthogonal')continue;let hit=false;for(let x=1;x<a.r.pts.length&&!hit;x++)for(let y=1;y<b.r.pts.length&&!hit;y++){const p=a.r.pts[x-1],q=a.r.pts[x],u=b.r.pts[y-1],v=b.r.pts[y];if(p.x===q.x&&u.y===v.y)hit=p.x>Math.min(u.x,v.x)&&p.x<Math.max(u.x,v.x)&&u.y>Math.min(p.y,q.y)&&u.y<Math.max(p.y,q.y);else if(p.y===q.y&&u.x===v.x)hit=u.x>Math.min(p.x,q.x)&&u.x<Math.max(p.x,q.x)&&p.y>Math.min(u.y,v.y)&&p.y<Math.max(u.y,v.y);}if(hit)crossings++;}
  checks.replaceChildren(el('p',`直角链路交叉 ${crossings} 对（最多检查前 200 条链路；几何交叉不表示物理连接）。`),table(['需核对项'],warnings.map(w=>[w])),table(['链路','类型','速率','端口','避障'],g.edges.map(e=>[e.label||'未命名',names[e.linkKind]||'未登记',e.speed||'未登记',`${e.sourceLabel||'未填'} → ${e.targetLabel||'未填'}`,e.avoid?'开启':'关闭'])));
}
function changeGroup(id,key){const g=api.graph(),r=g.groups.find(r=>r.id===id);r[key]=!r[key];api.update(g)}
const imp=panel('从设备与链路清单生成拓扑','导入两份 CSV 或直接粘贴。先预览，再替换当前图；可先下载现有完整文件。所有内容只在浏览器解析。');
const nodes=field('设备 CSV：id,type,label,address,group','textarea','id,type,label,address,group\ncore,switch,示例核心,192.0.2.1,核心区\napp,server,示例应用,192.0.2.10,服务器区'),edges=field('链路 CSV：from,to,label,speed,kind,sourcePort,targetPort','textarea','from,to,label,speed,kind,sourcePort,targetPort\ncore,app,示例上联,10 Gbps,fiber,Gi1/0/1,eth0');
for(const f of [nodes,edges])f.input.maxLength=128000;
const read=(input,target)=>{input.addEventListener('change',async()=>{try{const f=input.files[0];if(!f)return;if(f.size>128000)throw Error('每份 CSV 最多 128 KB');target.value=await f.text()}catch(e){alert(e.message)}finally{input.value=''}})};
const nf=el('input',null,{type:'file',accept:'.csv,text/csv'}),ef=el('input',null,{type:'file',accept:'.csv,text/csv'});read(nf,nodes.input);read(ef,edges.input);
imp.append(grid(nodes.label,edges.label),row(nf,ef,btn('预览生成结果',preview,'primary'),btn('导出当前设备与链路清单',()=>{const g=api.graph();download('拓扑设备.csv',csv([['id','type','label','address','group'],...g.nodes.map(n=>[n.id,n.type,n.label,n.address,(g.groups||[]).find(x=>x.id===n.groupId)?.label||''])]),'text/csv');download('拓扑链路.csv',csv([['from','to','label','speed','kind','sourcePort','targetPort'],...g.edges.map(e=>[e.from,e.to,e.label,e.speed,e.linkKind,e.sourceLabel,e.targetLabel])]),'text/csv')})));
function parse(text,header){const rows=parseCsv(text.replace(/^\ufeff/,''));if(rows.shift()?.join(',')!==header)throw Error('CSV 首行列名不符：'+header);return rows.filter(r=>r.some(v=>v.trim()))}
function preview(){const nr=parse(nodes.input.value,'id,type,label,address,group'),er=parse(edges.input.value,'from,to,label,speed,kind,sourcePort,targetPort'),groups=[...new Set(nr.map(r=>r[4]).filter(Boolean))].map(label=>({id:crypto.randomUUID(),label,color:'#2563eb',locked:false,hidden:false}));if(nr.some(r=>r.length!==5)||er.some(r=>r.length!==7))throw Error('CSV 列数不符');const graph=api.validate({format:'yj-topology',version:2,groups,nodes:nr.map(([id,type,label,address,group],i)=>({id,type,label,address,note:'',x:(i%4)*270,y:Math.floor(i/4)*190,color:'#2563eb',groupId:groups.find(g=>g.label===group)?.id||''})),edges:er.map(([from,to,label,speed,linkKind,sourceLabel,targetLabel])=>({id:crypto.randomUUID(),from,to,label,speed,linkKind,sourceLabel,targetLabel,note:'',routing:'orthogonal',avoid:nr.length<=50}))});const d=dialog('生成预览');d.append(el('p',`${graph.nodes.length} 个设备、${graph.edges.length} 条链路、${groups.length} 个区域。确认将替换当前拓扑，可用原有撤销恢复。`),table(['设备','地址','区域'],graph.nodes.map(n=>[n.label,n.address,groups.find(g=>g.id===n.groupId)?.label||'—'])),row(btn('先备份当前图',()=>document.getElementById('export-json').click()),btn('确认替换',()=>{api.update(graph);api.fit();d.close()},'primary'),btn('取消',()=>d.close())));d.showModal()}
let scheduled;window.addEventListener('yj-topology-update',()=>{clearTimeout(scheduled);scheduled=setTimeout(render,180)});render();
